const REVIEW_CATS = ['arch','searchfun','viz','eval','filter','correlate','fields','aliases','tags','macros','cim'];
const REVIEW_CATNAME = {
  arch:'Buckets & Architecture', searchfun:'Search Fundamentals', viz:'Visualizations & Charts',
  eval:'eval & Formatting', filter:'Filtering Results', correlate:'Correlating Events',
  fields:'Fields & Extractions', aliases:'Aliases & Calculated Fields', tags:'Tags & Event Types',
  macros:'Macros', cim:'CIM'
};
const REVIEW = [
  {c:'arch', q:`What is the only writeable bucket type?`, a:`The hot bucket.`},
  {c:'arch', q:`By what filter are indexes divided into buckets?`, a:`By time.`},

  {c:'searchfun', q:`What are the 4 types of searches by performance?`, a:`Dense, Sparse, Super Sparse, and Rare.`},
  {c:'searchfun', q:`In searches, what is the scanCount?`, a:`The number of events scanned for that particular search.`},

  {c:'viz', q:`What must the underlying search use to produce a multi-series table?`, a:`Reporting / transforming commands such as chart or timechart.`},
  {c:'viz', q:`What are the seven chart types?`, a:`Line, Area, Column, Bar, Bubble, Scatter, and Pie.`},
  {c:'viz', q:`What is a trait of scatter charts?`, a:`They show two dimensions - trends in the relationship between discrete data values.`},
  {c:'viz', q:`What is a trait of bubble charts?`, a:`They provide a visual way to view a three-dimensional series.`},
  {c:'viz', q:`What are two commonly used clauses for chart?`, a:`over and by.`},
  {c:'viz', q:`What do the over and by clauses do with chart?`, a:`They divide the data into sub-groupings.`},
  {c:'viz', q:`(T/F) You can only split chart results over two dimensions.`, a:`True.`},
  {c:'viz', q:`chart and timechart automatically limit results to how many values?`, a:`10 (the rest are grouped into "OTHER").`},
  {c:'viz', q:`What happens to the surplus values from chart / timechart?`, a:`They are grouped into a single "OTHER" category.`},
  {c:'viz', q:`(T/F) Null values are NOT shown by default by chart and timechart.`, a:`False - null values ARE shown by default (usenull defaults to true).`},
  {c:'viz', q:`What is always on the x-axis for timechart?`, a:`_time.`},
  {c:'viz', q:`(T/F) Functions and arguments used with stats/chart cannot be used with timechart.`, a:`False - they can be used with timechart too.`},
  {c:'viz', q:`(T/F) You can split timechart by two fields.`, a:`False - timechart can split by only one field.`},
  {c:'viz', q:`What argument adjusts the sampling interval of timechart?`, a:`span.`},
  {c:'viz', q:`What does the trendline command do?`, a:`Overlays a computed moving average on a chart.`},
  {c:'viz', q:`What is the syntax of the trendline command?`, a:`trendline <trendtype><period>(field) [AS newfield]`},
  {c:'viz', q:`What command looks up and adds location information to an event?`, a:`iplocation.`},
  {c:'viz', q:`What information does iplocation include?`, a:`City, Country, Region, Latitude, and Longitude.`},
  {c:'viz', q:`What is the data requirement for the geostats command?`, a:`The data must include latitude and longitude values.`},
  {c:'viz', q:`Which arguments control column counts for geostats?`, a:`globallimit and locallimit.`},
  {c:'viz', q:`Which command computes statistical functions and renders a cluster map?`, a:`geostats.`},
  {c:'viz', q:`Which command shows relative metrics for predefined geographic regions?`, a:`geom.`},
  {c:'viz', q:`(T/F) A sparkline is an inline chart that can be added to a stats/chart table.`, a:`True - sparkline() is an inline mini-chart used with the stats and chart commands. (Note: NOT timechart, which is already a time series.)`},
  {c:'viz', q:`(T/F) Automatic totaling of every column can be done using the Format option.`, a:`True.`},
  {c:'viz', q:`Which command adds a total of all or selected fields?`, a:`addtotals.`},
  {c:'viz', q:`What does the row option (row=t) do for addtotals?`, a:`Creates a column that contains numeric totals for each row.`},
  {c:'viz', q:`What does the col option (col=t) do for addtotals?`, a:`Creates a row that contains numeric totals for each column.`},
  {c:'viz', q:`What does the labelfield option specify for addtotals?`, a:`Which field the label is placed in (usually the leftmost / first field).`},

  {c:'eval', q:`What can the eval command be used for?`, a:`Perform calculations; convert, round, and format values; and use conditional statements.`},
  {c:'eval', q:`Which command lets you calculate and manipulate field values in your report?`, a:`eval.`},
  {c:'eval', q:`(T/F) Results of eval can be written to an existing field.`, a:`True.`},
  {c:'eval', q:`What happens if the eval destination field is the same as an existing field?`, a:`The existing field value is overwritten by the eval result.`},
  {c:'eval', q:`(T/F) Indexed data is modified after eval overwrites a field value.`, a:`False - eval runs at search time; the indexed data is never changed.`},
  {c:'eval', q:`Which operator is used for concatenation in eval?`, a:`The period ( . ). The + operator is arithmetic only and will NOT concatenate strings.`},
  {c:'eval', q:`Which function sets a field value to a specified number of decimals?`, a:`round().`},
  {c:'eval', q:`(T/F) The tostring function can be used with eval.`, a:`True.`},
  {c:'eval', q:`How can eval format numeric field values as strings?`, a:`With tostring() - adding characters such as commas, "duration", or "hex" to the values.`},
  {c:'eval', q:`What separator is used between multiple expressions in one eval command?`, a:`A comma.`},
  {c:'eval', q:`eval SalesTerritory = if((VendorID>=7000 AND VendorID<8000),"Asia","Rest of the World") - value for VendorID 80000?`, a:`"Rest of the World" (80000 is not < 8000, so the false branch is used).`},

  {c:'filter', q:`(T/F) The search command treats field values in a case-insensitive manner.`, a:`True.`},
  {c:'filter', q:`(T/F) The where command treats field values in a case-insensitive manner.`, a:`False - where is case-sensitive.`},
  {c:'filter', q:`(T/F) Unquoted or single-quoted strings are treated as fields.`, a:`True (double-quoted strings are treated as literal values).`},
  {c:'filter', q:`Which operator enables wildcard searches with the where command?`, a:`like (using % and _ as wildcards).`},
  {c:'filter', q:`What is the fillnull value used for?`, a:`To replace null values in fields; the default replacement value is 0.`},

  {c:'correlate', q:`What is a transaction?`, a:`Any group of related events that span time.`},
  {c:'correlate', q:`What is the syntax of the transaction command?`, a:`transaction <field-list> - a list of one or more fields.`},
  {c:'correlate', q:`(T/F) The transaction command creates a single event from a group of events.`, a:`True.`},
  {c:'correlate', q:`Which field is produced by the transaction command?`, a:`duration - the difference between the first and last event timestamps (also eventcount).`},
  {c:'correlate', q:`What does the maxspan argument do for transaction?`, a:`Defines the maximum total time between the earliest and latest events.`},
  {c:'correlate', q:`What does the maxpause argument do for transaction?`, a:`Sets the maximum gap (pause) allowed between two consecutive events.`},
  {c:'correlate', q:`transaction clientip JSESSIONID startswith=eval(action="addtocart") endswith=eval(action="purchase") - what is true of the events?`, a:`Each transaction's first event has action "addtocart" and its last event has action "purchase".`},
  {c:'correlate', q:`What is the default limit on the number of events per transaction?`, a:`1000.`},
  {c:'correlate', q:`Why is stats recommended over transaction?`, a:`It is faster and more efficient.`},
  {c:'correlate', q:`When do you need to use transaction?`, a:`When you need events correlated together, or must define event grouping based on start/end values or time segments.`},
  {c:'correlate', q:`How can admins change the max number of events per transaction?`, a:`Configure the transaction limits in limits.conf (the maxevents option controls it; default 1000).`},

  {c:'fields', q:`What are knowledge objects?`, a:`Tools you use to discover and analyze various aspects of your data.`},
  {c:'fields', q:`(T/F) Knowledge objects are shareable, reusable, and searchable.`, a:`True.`},
  {c:'fields', q:`(T/F) The Power User role can create an object that persists globally across all apps.`, a:`False - a Power User can share only up to the App level, not Global.`},
  {c:'fields', q:`(T/F) The Power User role can create an object that persists in the context of a specific app.`, a:`True.`},
  {c:'fields', q:`Which meta fields are stored in the index prior to search time?`, a:`host, source, and sourcetype.`},
  {c:'fields', q:`Which internal fields are stored in the index prior to search time?`, a:`_time and _raw.`},
  {c:'fields', q:`At what time does field discovery find fields related to the search results?`, a:`Search time.`},
  {c:'fields', q:`(T/F) After extracting fields with the Field Extractor, you can share them.`, a:`True - extracted fields exist as knowledge objects.`},
  {c:'fields', q:`What are the two methods for field extraction?`, a:`Regex and delimiter.`},

  {c:'aliases', q:`Which knowledge object provides a way of normalizing data over any default field?`, a:`Field aliases.`},
  {c:'aliases', q:`(T/F) Field aliases are applied after field extraction, before lookups.`, a:`True.`},
  {c:'aliases', q:`(T/F) It is not possible to apply field aliases to lookups.`, a:`False - you can apply aliases to lookup fields.`},
  {c:'aliases', q:`(T/F) Multiple aliases can be applied to one field.`, a:`True.`},
  {c:'aliases', q:`(T/F) After a field alias is made, it can be used as an ordinary field in SPL.`, a:`True.`},
  {c:'aliases', q:`What is a calculated field?`, a:`A shortcut for performing repetitive, long, or complex transformations using the eval command.`},
  {c:'aliases', q:`What must a calculated field be based on?`, a:`An extracted field.`},
  {c:'aliases', q:`Where are calculated fields and field aliases set up in the GUI?`, a:`Settings → Fields.`},

  {c:'tags', q:`Which knowledge objects are like nicknames created for related field/value pairs?`, a:`Tags.`},
  {c:'tags', q:`(T/F) Tags are case-sensitive.`, a:`True.`},
  {c:'tags', q:`(T/F) You can only create one tag for any field/value combination.`, a:`False - a field/value pair can have many tags.`},
  {c:'tags', q:`(T/F) Knowledge objects like tags, field aliases, and calculated fields are searchable.`, a:`True.`},
  {c:'tags', q:`How does a tag appear after being selected?`, a:`In the results as tags, in parentheses next to the associated field/value pairs.`},
  {c:'tags', q:`What is the syntax for searching for a tag associated with a value?`, a:`tag=<tag name>`},
  {c:'tags', q:`What is the syntax for searching for a tag on a specific field?`, a:`tag::<field>=<tagname>`},
  {c:'tags', q:`Where can tag settings (including permissions) be edited?`, a:`Settings → Tags → List by field value pair.`},
  {c:'tags', q:`Which knowledge object groups similar types of events?`, a:`Event types.`},
  {c:'tags', q:`How do you create an event type?`, a:`Create and run a search, then Save As → Event Type.`},
  {c:'tags', q:`(T/F) Event type names can contain spaces.`, a:`False.`},
  {c:'tags', q:`Which criteria are reviewed/refined in the Event Type Builder?`, a:`Search string, field values, and tags.`},
  {c:'tags', q:`What is the syntax for using event types in a search?`, a:`eventtype=<eventtype_name>`},
  {c:'tags', q:`At what time does Splunk evaluate events for event types?`, a:`Search time.`},
  {c:'tags', q:`How can you tag event types in the GUI?`, a:`Settings → Event Types, or Event details → Actions.`},
  {c:'tags', q:`(T/F) It is not possible to add a tag to an event type.`, a:`False - event types can be tagged.`},
  {c:'tags', q:`(T/F) Event types do not include a time range, while a saved report does.`, a:`True.`},
  {c:'tags', q:`What happens if an event fits into multiple event types?`, a:`Priority decides which event type takes precedence in the display order.`},

  {c:'macros', q:`Which knowledge objects are useful when you frequently run searches/reports with similar syntax?`, a:`Macros.`},
  {c:'macros', q:`(T/F) Macros are shareable.`, a:`True.`},
  {c:'macros', q:`At what time are parameter values passed to a macro?`, a:`At execution time.`},
  {c:'macros', q:`How do you create a macro in the GUI?`, a:`Settings → Advanced Search → Search macros.`},
  {c:'macros', q:`What is the syntax for using a macro in a search?`, a:`Wrap the macro name in backticks:  &#96;macro&#96;`},

  {c:'cim', q:`What is the Splunk Common Information Model (CIM)?`, a:`A methodology for normalizing data so you can easily correlate data from different sources and sourcetypes.`},
];

/* Command Face-Off deck: a common command/function, a real example, and the command it is most often confused with. */
const COMMANDS = [
 {cat:'Transforming', name:'stats', use:`Aggregates events into a statistics table using functions like count, sum, and avg.`, ex:`... | stats count by status`, vs:'chart', diff:`<b>stats</b> groups by one or more fields as rows. <b>chart</b> adds a second dimension, splitting results into columns with <code>over X by Y</code>.`, d:SR+'Stats'},
 {cat:'Transforming', name:'chart', use:`Builds a table or visualization across two dimensions you choose.`, ex:`... | chart count over host by status`, vs:'timechart', diff:`<b>chart</b> lets you pick any x-axis with <code>over</code>. <b>timechart</b> is the same idea but the x-axis is always <code>_time</code>.`, d:SR+'Chart'},
 {cat:'Transforming', name:'timechart', use:`Aggregates data over time. The x-axis is always _time.`, ex:`... | timechart span=1h count by host`, vs:'chart', diff:`<b>timechart</b> is locked to time and can split by only one field. <b>chart</b> lets you choose any field for the x-axis.`, d:SR+'Timechart'},
 {cat:'Eval', name:'eval', use:`Creates or modifies a field using an expression or function.`, ex:`... | eval mb = bytes/1024/1024`, vs:'where', diff:`<b>eval</b> computes a value and assigns it to a field. <b>where</b> uses the same functions but to <b>filter</b> rows, keeping only those where the expression is true.`, d:SR+'Eval'},
 {cat:'Filtering', name:'where', use:`Filters results using boolean expressions and functions.`, ex:`... | where bytes > avg_bytes`, vs:'search', diff:`<b>where</b> can compare two fields and uses functions like <code>like()</code> and <code>isnull()</code>. <b>search</b> matches raw terms and uses <code>*</code> wildcards.`, d:SR+'Where'},
 {cat:'Filtering', name:'search', use:`Filters events by keywords and field=value terms.`, ex:`... | search status=404 host=web*`, vs:'where', diff:`<b>search</b> uses <code>*</code> wildcards and matches raw terms. <b>where</b> needs <code>like(field,"%..%")</code> and can compare one field to another.`, d:SR+'Search'},
 {cat:'Fields', name:'rex', use:`Extracts fields at search time using a regex you supply.`, ex:`... | rex "user=(?&lt;user&gt;\\w+)"`, vs:'erex', diff:`<b>rex</b> requires you to write the regex. <b>erex</b> generates the regex for you from example values. Both are temporary (that search only).`, d:SR+'Rex'},
 {cat:'Fields', name:'erex', use:`Generates a field-extraction regex from example values.`, ex:`... | erex user examples="jdoe,asmith"`, vs:'rex', diff:`<b>erex</b> writes the regex from examples, no regex skills needed. <b>rex</b> applies a regex you already wrote.`, d:SR+'Erex'},
 {cat:'Enrich', name:'lookup', use:`Adds fields to events by matching them against a lookup table.`, ex:`... | lookup http_status code OUTPUT description`, vs:'inputlookup', diff:`<b>lookup</b> enriches events you already have. <b>inputlookup</b> outputs the whole table itself as results.`, d:SR+'Lookup'},
 {cat:'Enrich', name:'inputlookup', use:`Reads a lookup table and returns its rows as results.`, ex:`| inputlookup vip_users.csv`, vs:'outputlookup', diff:`<b>inputlookup</b> loads a table in (leading <code>|</code>). <b>outputlookup</b> writes your current results out to a table.`, d:SR+'Inputlookup'},
 {cat:'Enrich', name:'outputlookup', use:`Writes search results into a lookup table (CSV or KV Store).`, ex:`... | outputlookup daily_totals.csv`, vs:'inputlookup', diff:`<b>outputlookup</b> saves results to a table. <b>inputlookup</b> reads a table back out as events.`, d:SR+'Outputlookup'},
 {cat:'Correlate', name:'join', use:`Merges a subsearch on a common field, SQL-style.`, ex:`... | join user [search index=hr | fields user dept]`, vs:'union', diff:`<b>join</b> matches rows on a key and is limited to two datasets. <b>union</b> just stacks two or more datasets together.`, d:SR+'Join'},
 {cat:'Correlate', name:'union', use:`Combines results of two or more datasets by stacking them.`, ex:`| union [search index=a] [search index=b]`, vs:'append', diff:`<b>union</b> merges 2+ datasets. <b>append</b> tacks a single subsearch's rows onto the end of the current results.`, d:SR+'Union'},
 {cat:'Correlate', name:'append', use:`Adds subsearch results to the end of the results as new rows.`, ex:`... | append [search index=old | stats count]`, vs:'appendcols', diff:`<b>append</b> adds rows at the bottom. <b>appendcols</b> adds the subsearch's values as new columns on existing rows.`, d:SR+'Append'},
 {cat:'Correlate', name:'appendcols', use:`Adds subsearch values as new columns to existing rows.`, ex:`... | appendcols [search ... | stats avg(x)]`, vs:'append', diff:`<b>appendcols</b> lines rows up positionally, so both searches need the same count and order. <b>append</b> just adds rows underneath.`, d:SR+'Appendcols'},
 {cat:'Correlate', name:'transaction', use:`Groups related events into one multi-event transaction.`, ex:`... | transaction clientip maxspan=30s`, vs:'stats', diff:`<b>transaction</b> keeps the raw events and adds <code>duration</code>/<code>eventcount</code>, but is resource-heavy. <b>stats by field</b> is faster when you only need aggregates.`, d:SR+'Transaction'},
 {cat:'Filtering', name:'dedup', use:`Removes duplicate events for the specified fields.`, ex:`... | dedup host`, vs:'stats', diff:`<b>dedup</b> keeps the first event per unique value. <b>stats</b> can also dedupe via <code>count by</code> or <code>values()</code> while aggregating.`, d:SR+'Dedup'},
 {cat:'Transforming', name:'top', use:`Shows the most common values with count and percent.`, ex:`... | top limit=5 url`, vs:'rare', diff:`<b>top</b> returns the most frequent values. <b>rare</b> returns the least frequent. Both accept <code>by</code> and <code>limit</code>.`, d:SR+'Top'},
 {cat:'Fields', name:'table', use:`Displays specified fields as columns, keeping your order.`, ex:`... | table _time host status`, vs:'fields', diff:`<b>table</b> is for display and keeps only listed fields as columns. <b>fields</b> adds or removes fields from the pipeline (use <code>fields - x</code> to drop).`, d:SR+'Table'},
 {cat:'Fields', name:'fields', use:`Keeps or removes fields to speed up a search.`, ex:`... | fields - _raw`, vs:'table', diff:`<b>fields</b> controls which fields flow through the pipeline (performance). <b>table</b> formats fields for final display.`, d:SR+'Fields'},
 {cat:'Transforming', name:'eventstats', use:`Adds aggregate values to every event without collapsing them.`, ex:`... | eventstats avg(bytes) as avg_b`, vs:'stats', diff:`<b>stats</b> collapses events into a summary table. <b>eventstats</b> computes the same aggregates but keeps every event, adding the result as a new field.`, d:SR+'Eventstats'},
 {cat:'Transforming', name:'streamstats', use:`Computes running, cumulative aggregates as events stream by.`, ex:`... | streamstats sum(bytes) as running`, vs:'eventstats', diff:`<b>streamstats</b> builds a running total up to each event (order matters). <b>eventstats</b> gives the same overall value to every event.`, d:SR+'Streamstats'},
 {cat:'Fields', name:'fillnull', use:`Replaces null field values with a value (default 0).`, ex:`... | fillnull value=0 bytes`, vs:'filldown', diff:`<b>fillnull</b> replaces nulls with a fixed value. <b>filldown</b> carries the last non-null value downward into the blanks.`, d:SR+'Fillnull'},
 {cat:'Fields', name:'rename', use:`Renames a field for display in this search.`, ex:`... | rename src AS source`, vs:'field alias', diff:`<b>rename</b> changes a field name for that search only. A <b>field alias</b> (knowledge object) adds an alternate name permanently without removing the original.`, d:SR+'Rename'},
 {cat:'Transforming', name:'sort', use:`Sorts results ascending or descending by a field; can limit the count.`, ex:`... | sort 100 -src_ip`, vs:'reverse', diff:`<b>sort</b> orders by a field (a <code>-</code> prefix means descending; ascending is the default). <b>reverse</b> just flips the current result order without regard to any field.`, d:SR+'Sort'},
 {cat:'Function', name:'values()', use:`Returns the unique values of a field, sorted, as a multivalue list.`, ex:`... | stats values(action) by user`, vs:'list()', diff:`<b>values()</b> returns <b>distinct</b> values, sorted alphabetically. <b>list()</b> returns <b>all</b> values in the order seen (up to 100), including duplicates.`, d:SR+'CommonStatsFunctions'},
 {cat:'Function', name:'count()', use:`Counts events, or occurrences of a specific field.`, ex:`... | stats count(action) as actions`, vs:'dc()', diff:`<b>count()</b> counts how many events (or field occurrences) there are. <b>dc()</b> counts the number of <b>distinct</b> values, ignoring duplicates.`, d:SR+'CommonStatsFunctions'},
];
